def _brief(kwargs: dict, maxlen: int = 80) -> str:
    s = ", ".join(f"{k}={repr(v)[:40]}" for k, v in kwargs.items())
    return s[:maxlen] + ("..." if len(s) > maxlen else "")

def _summarize_old(self, messages: list[dict], llm: LLM | None,
                       keep_recent: int = 8) -> bool:
        """Layer 2: Summarize old conversation, keep recent messages intact."""
        if len(messages) <= keep_recent:
            return False

split = self._safe_split(messages, keep_recent)
        old = messages[:split]
        tail = messages[split:]

summary = self._get_summary(old, llm)

messages.clear()
        messages.append({
            "role": "user",
            "content": f"[Context compressed - conversation summary]\n{summary}",
        })
        messages.append({
            "role": "assistant",
            "content": "Got it, I have the context from our earlier conversation.",
        })
        messages.extend(tail)
        return True

def _hard_collapse(self, messages: list[dict], llm: LLM | None):
        """Layer 3: Emergency compression. Keep only last 4 messages + summary."""
        split = self._safe_split(messages, 4 if len(messages) > 4 else 2)
        tail = messages[split:]
        summary = self._get_summary(messages[:split], llm)

messages.clear()
        messages.append({
            "role": "user",
            "content": f"[Hard context reset]\n{summary}",
        })
        messages.append({
            "role": "assistant",
            "content": "Context restored. Continuing from where we left off.",
        })
        messages.extend(tail)

def _get_summary(self, messages: list[dict], llm: LLM | None) -> str:
        """Generate summary via LLM or fallback to extraction."""
        flat = self._flatten(messages)

if llm:
            try:
                resp = llm.chat(
                    messages=[
                        {
                            "role": "system",
                            "content": (
                                "Compress this conversation into a brief summary. "
                                "Preserve: file paths edited, key decisions made, "
                                "errors encountered, current task state. "
                                "Drop: verbose command output, code listings, "
                                "redundant back-and-forth."
                            ),
                        },
                        {"role": "user", "content": flat[:15000]},
                    ],
                )
                return resp.content
            except Exception:
                pass

# fallback: extract key lines
        return self._extract_key_info(messages)

@staticmethod
    def _flatten(messages: list[dict]) -> str:
        parts = []
        for m in messages:
            role = m.get("role", "?")
            text = m.get("content", "") or ""
            if text:
                parts.append(f"[{role}] {text[:400]}")
        return "\n".join(parts)

@staticmethod
    def _extract_key_info(messages: list[dict]) -> str:
        """Fallback: extract file paths, errors, and decisions without LLM."""
        import re
        files_seen = set()
        errors = []

for m in messages:
            text = m.get("content", "") or ""
            # extract file paths
            for match in re.finditer(r'[\w./\-]+\.\w{1,5}', text):
                files_seen.add(match.group())
            # extract error lines
            for line in text.splitlines():
                if "error" in line.lower():
                    errors.append(line.strip()[:150])

parts = []
        if files_seen:
            parts.append(f"Files touched: {', '.join(sorted(files_seen)[:20])}")
        if errors:
            parts.append(f"Errors seen: {'; '.join(errors[:5])}")
        return "\n".join(parts) or "(no extractable context)"

def list_documents(self) -> list[dict]:
        """列出所有已索引的文档及其统计。"""
        sources = {}
        for c in self._chunks:
            src = c.get("source", "unknown")
            if src not in sources:
                sources[src] = {"chunks": 0, "chars": 0}
            sources[src]["chunks"] += 1
            sources[src]["chars"] += len(c.get("content", ""))
        return [
            {"source": s, "chunks": v["chunks"], "chars": v["chars"]}
            for s, v in sorted(sources.items())
        ]

def search(self, query: str, top_k: int = 5) -> list[dict]:
        """搜索知识库。先尝试语义搜索，回退到关键词搜索。"""
        if not self._chunks:
            return []

# 尝试语义搜索（需要 embedding API）
        results = self._semantic_search(query, top_k)
        if results is not None:
            return results

# 回退：关键词搜索
        return self._keyword_search(query, top_k)

def rebuild(self) -> str:
        """重建索引（从已存储的源文件路径重新读取）。"""
        # 收集所有不同的源文件路径
        sources = set()
        for chunk in self._chunks:
            src = chunk.get("source", "")
            if src:
                sources.add(src)

old_count = len(self._chunks)
        self._chunks = []

files_scanned = 0
        for src_path in sorted(sources):
            p = Path(src_path)
            if p.exists():
                self._add_file(p, save=False)
                files_scanned += 1

self._save_index()
        if files_scanned > 0:
            return f"Rebuilt index: {files_scanned} files scanned, {len(self._chunks)} chunks total"
        else:
            return f"No source files found. Use 'infracoder kb add <path>' to add documents."

def stats(self) -> str:
        """知识库统计信息。"""
        return (
            f"Knowledge base: {len(self._chunks)} chunks from "
            f"{len(self.list_documents())} documents"
        )

# ---- 内部方法 ----

def _add_file(self, path: Path, save: bool = True) -> str:
        """索引单个文件。"""
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except Exception as e:
            return f"Error reading {path}: {e}"

chunks = self._chunk_text(text, path)
        new_count = 0
        for chunk in chunks:
            # 检查是否已存在（按 content 去重）
            if not any(c["content"] == chunk["content"] for c in self._chunks):
                self._chunks.append(chunk)
                new_count += 1

if save:
            self._sources.append(str(path))
            self._save_index()
        return f"Indexed {path.name}: {new_count} new chunks"

def _add_directory(self, path: Path) -> str:
        """索引整个目录。"""
        total = 0
        results = []
        for ext in SUPPORTED_EXTENSIONS:
            for f in sorted(path.rglob(f"*{ext}")):
                if f.name.startswith("."):
                    continue
                result = self._add_file(f, save=False)
                total += 1
                results.append(result)
        self._save_index()
        docs = self.list_documents()
        return f"Indexed {total} files, {len(self._chunks)} chunks total"

def _chunk_text(self, text: str, source_path: Path) -> list[dict]:
        """将文本按段落分块，返回块列表。"""
        chunks = []
        source = str(source_path)

# 按空行分割段落
        paragraphs = re.split(r"\n\s*\n", text)

current_chunk = ""
        for para in paragraphs:
            para = para.strip()
            if not para:
                continue

if len(current_chunk) + len(para) < CHUNK_MAX_CHARS:
                current_chunk += "\n\n" + para if current_chunk else para
            else:
                if current_chunk and len(current_chunk) >= CHUNK_MIN_CHARS:
                    chunks.append(self._make_chunk(current_chunk, source))
                current_chunk = para

if current_chunk and len(current_chunk) >= CHUNK_MIN_CHARS:
            chunks.append(self._make_chunk(current_chunk, source))

return chunks

def _make_chunk(self, content: str, source: str) -> dict:
        """创建一个块条目。"""
        return {
            "id": f"{source}:#{hash(content) % 10000000}",
            "source": source,
            "content": content,
            "keywords": self._extract_keywords(content),
            "added_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        }

@staticmethod
    def _extract_keywords(text: str) -> list[str]:
        """提取关键词（用于关键词搜索）。"""
        # 提取英文词和中文字符
        words = []
        for match in re.finditer(r"[a-zA-Z]+|[\u4e00-\u9fff]+", text.lower()):
            w = match.group()
            if re.match(r"^[\u4e00-\u9fff]+$", w):
                # 中文：拆成单个字和二元组
                for i in range(len(w)):
                    words.append(w[i])
                for i in range(len(w) - 1):
                    words.append(w[i:i+2])
            else:
                words.append(w)
        # 停用词表
        stopwords = {
            "the", "a", "an", "is", "are", "was", "were", "be", "been", "being",
            "have", "has", "had", "do", "does", "did", "will", "would", "could",
            "should", "may", "might", "shall", "can", "need", "dare", "ought",
            "used", "to", "of", "in", "for", "on", "with", "at", "by", "from",
            "as", "into", "through", "during", "before", "after", "above",
            "below", "between", "out", "off", "over", "under", "again",
            "further", "then", "once", "here", "there", "when", "where", "why",
            "how", "all", "each", "every", "both", "few", "more", "most",
            "other", "some", "such", "no", "nor", "not", "only", "own", "same",
            "so", "than", "too", "very", "just", "because", "but", "and", "or",
            "if", "while", "this", "that", "these", "those", "it", "its",
        }
        return [w for w in words if w not in stopwords and len(w) > 1]

def _keyword_search(self, query: str, top_k: int = 5) -> list[dict]:
        """基于关键词匹配的搜索。"""
        query_keywords = set(self._extract_keywords(query))
        if not query_keywords:
            return []

scored = []
        for chunk in self._chunks:
            chunk_keywords = set(chunk.get("keywords", []))
            matches = len(query_keywords & chunk_keywords)
            if matches > 0:
                scored.append((matches, chunk))

def cosine_sim(a, b):
                """计算余弦相似度。"""
                dot = sum(x * y for x, y in zip(a, b))
                na = math.sqrt(sum(x * x for x in a))
                nb = math.sqrt(sum(x * x for x in b))
                return dot / (na * nb) if na and nb else 0

scored = []
            for chunk in self._chunks:
                emb = chunk.get("embedding")
                if emb:
                    sim = cosine_sim(q_emb, emb)
                    scored.append((sim, chunk))

scored.sort(key=lambda x: -x[0])
            return [
                {
                    "source": c["source"],
                    "content": c["content"][:500],
                    "score": round(s, 4),
                }
                for s, c in scored[:top_k]
            ]

except Exception as e:
            # embedding 失败时静默回退到关键词搜索
            return None

def _load_index(self):
        """从磁盘加载索引。"""
        if self._index_path.exists():
            try:
                data = json.loads(self._index_path.read_text(encoding="utf-8"))
                self._chunks = data.get("chunks", [])
                self._sources = data.get("sources", [])
            except (json.JSONDecodeError, OSError):
                self._chunks = []
                self._sources = []

def _save_index(self):
        """将索引保存到磁盘。"""
        # 收集所有源文件路径用于重建
        sources = list(set(c.get("source", "") for c in self._chunks if c.get("source")))
        data = {"chunks": self._chunks, "sources": sources, "updated_at": time.strftime("%Y-%m-%d %H:%M:%S")}
        self._index_path.write_text(
            json.dumps(data, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )

"""LLM provider layer - thin wrapper over OpenAI-compatible APIs.

Since most providers (DeepSeek, Qwen, Kimi, GLM, Ollama, etc.) expose an
OpenAI-compatible endpoint, we just use the openai SDK directly.  Switch
provider by changing OPENAI_BASE_URL + OPENAI_API_KEY. That's it.

For providers that are NOT OpenAI-compatible (AWS Bedrock, Google Vertex,
etc.), use the LiteLLM backend which routes to 100+ providers through a
single unified interface.
"""

import json
import time
from dataclasses import dataclass, field

from openai import OpenAI, APIError, BadRequestError, RateLimitError, APITimeoutError, APIConnectionError

@dataclass
class ToolCall:
    id: str
    name: str
    arguments: dict

@dataclass
class LLMResponse:
    content: str = ""
    tool_calls: list[ToolCall] = field(default_factory=list)
    prompt_tokens: int = 0
    completion_tokens: int = 0

@property
    def message(self) -> dict:
        """Convert to OpenAI message format for appending to history."""
        msg: dict = {"role": "assistant", "content": self.content or None}
        if self.tool_calls:
            msg["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": "function",
                    "function": {
                        "name": tc.name,
                        "arguments": json.dumps(tc.arguments),
                    },
                }
                for tc in self.tool_calls
            ]
        return msg

def chat(
        self,
        messages: list[dict],
        tools: list[dict] | None = None,
        on_token=None,
    ) -> LLMResponse:
        """Send messages, stream back response, handle tool calls."""
        params: dict = {
            "model": self.model,
            "messages": messages,
            "stream": True,
            **self.extra,
        }
        if tools:
            params["tools"] = tools

# stream_options is an OpenAI extension; fall back only when the provider
        # rejects the param (400 BadRequest), not on transient errors that
        # _call_with_retry already exhausted - otherwise we'd double the retries
        params["stream_options"] = {"include_usage": True}
        try:
            stream = self._call_with_retry(params)
        except BadRequestError:
            params.pop("stream_options", None)
            stream = self._call_with_retry(params)

content_parts: list[str] = []
        tc_map: dict[int, dict] = {}  # index -> {id, name, arguments_str}
        prompt_tok = 0
        completion_tok = 0

for chunk in stream:
            # usage info comes in the final chunk
            if chunk.usage:
                # some providers send usage with null fields; coerce to 0 so the
                # running totals below don't blow up on int + None
                prompt_tok = chunk.usage.prompt_tokens or 0
                completion_tok = chunk.usage.completion_tokens or 0

if not chunk.choices:
                continue
            delta = chunk.choices[0].delta

# accumulate text
            if delta.content:
                content_parts.append(delta.content)
                if on_token:
                    on_token(delta.content)

# accumulate tool calls across chunks
            if delta.tool_calls:
                for tc_delta in delta.tool_calls:
                    idx = tc_delta.index
                    if idx not in tc_map:
                        tc_map[idx] = {"id": "", "name": "", "args": ""}
                    if tc_delta.id:
                        tc_map[idx]["id"] = tc_delta.id
                    if tc_delta.function:
                        if tc_delta.function.name:
                            tc_map[idx]["name"] = tc_delta.function.name
                        if tc_delta.function.arguments:
                            tc_map[idx]["args"] += tc_delta.function.arguments

# parse accumulated tool calls
        parsed: list[ToolCall] = []
        for idx in sorted(tc_map):
            raw = tc_map[idx]
            try:
                args = json.loads(raw["args"])
            except (json.JSONDecodeError, KeyError):
                args = {}
            parsed.append(ToolCall(id=raw["id"], name=raw["name"], arguments=args))

self.total_prompt_tokens += prompt_tok
        self.total_completion_tokens += completion_tok

return LLMResponse(
            content="".join(content_parts),
            tool_calls=parsed,
            prompt_tokens=prompt_tok,
            completion_tokens=completion_tok,
        )

def chat(
        self,
        messages: list[dict],
        tools: list[dict] | None = None,
        on_token=None,
    ) -> LLMResponse:
        """Send messages via litellm, stream back response, handle tool calls."""
        params: dict = {
            "model": self.model,
            "messages": messages,
            "stream": True,
            **self.extra,
        }
        if tools:
            params["tools"] = tools

# ask for usage stats in the final chunk; litellm drops this for providers
        # that don't support it (drop_params), so it's safe to always request
        params["stream_options"] = {"include_usage": True}
        stream = self._call_with_retry(params)

content_parts: list[str] = []
        tc_map: dict[int, dict] = {}
        prompt_tok = 0
        completion_tok = 0

for chunk in stream:
            usage = getattr(chunk, "usage", None)
            if usage:
                prompt_tok = getattr(usage, "prompt_tokens", 0) or 0
                completion_tok = getattr(usage, "completion_tokens", 0) or 0

if not getattr(chunk, "choices", None):
                continue
            delta = chunk.choices[0].delta

if getattr(delta, "content", None):
                content_parts.append(delta.content)
                if on_token:
                    on_token(delta.content)

if getattr(delta, "tool_calls", None):
                for tc_delta in delta.tool_calls:
                    idx = tc_delta.index
                    if idx not in tc_map:
                        tc_map[idx] = {"id": "", "name": "", "args": ""}
                    if tc_delta.id:
                        tc_map[idx]["id"] = tc_delta.id
                    if tc_delta.function:
                        if tc_delta.function.name:
                            tc_map[idx]["name"] = tc_delta.function.name
                        if tc_delta.function.arguments:
                            tc_map[idx]["args"] += tc_delta.function.arguments

parsed: list[ToolCall] = []
        for idx in sorted(tc_map):
            raw = tc_map[idx]
            try:
                args = json.loads(raw["args"])
            except (json.JSONDecodeError, KeyError):
                args = {}
            parsed.append(ToolCall(id=raw["id"], name=raw["name"], arguments=args))

self.total_prompt_tokens += prompt_tok
        self.total_completion_tokens += completion_tok

return LLMResponse(
            content="".join(content_parts),
            tool_calls=parsed,
            prompt_tokens=prompt_tok,
            completion_tokens=completion_tok,
        )

def _call_with_retry(self, params: dict, max_retries: int = 3):
        """Retry on transient errors with exponential backoff via litellm."""
        import litellm

params["drop_params"] = True
        if self.api_key:
            params["api_key"] = self.api_key
        if self.base_url:
            params["api_base"] = self.base_url

for attempt in range(max_retries):
            try:
                return litellm.completion(**params)
            except Exception as e:
                err = str(e).lower()
                is_transient = any(
                    kw in err
                    for kw in ["rate_limit", "timeout", "connection", "502", "503", "529"]
                )
                is_server = any(kw in err for kw in ["500", "502", "503", "504"])
                if (is_transient or is_server) and attempt < max_retries - 1:
                    time.sleep(2 ** attempt)
                else:
                    raise

